import type { BankItem, Difficulty } from './types';

/**
 * More grade 3-5 word-study items (prefixes and suffixes, Greek and Latin
 * roots, figurative language, homophones), added so these topics repeat less
 * often. Same rules and topic keys as readingBank.ts. Every prompt here is
 * unique across the combined bank (see readingBankMoreWords.test.ts).
 */
function q(
  topic: string,
  difficulty: Difficulty,
  prompt: string,
  answer: string,
  wrong: string[],
  explanation: string,
): BankItem {
  return { topic, difficulty, prompt, answer, wrong, explanation };
}

